// Spectrum analyzer window (bsc lan analyzer) — the detached surface opened by
// `bsc widget open spectrum`. A WATERFALL above, what the assistant can say
// below.
//
// WHY A SEPARATE WINDOW. It survives the main surface being wedged, which is
// also why the window is built by the app's Rust side rather than by this web
// view — an escape hatch routed through the thing it escapes is not one.
//
// WHY A WATERFALL AND NOT A BAR CHART. A bar per bin answers "what does this
// channel look like right now" and discards the two things an operator watches
// for: where a signal sits in the BAND, and how long it has been there. A burst
// and a permanent emitter draw the same bar. Here x is frequency across
// everything we can see, y is time with the newest window on top, and colour is
// signal strength — so duration stops being a number and becomes vertical
// extent. A persistent emitter is a stripe; a burst is a dash.
//
// THE SPAN IS WHAT WE OBSERVED, NEVER A BAND CONSTANT. The radio is parked on
// one channel today, so the axis is that channel's 20 MHz; hopping widens it and
// the axis follows. Drawing 2400-2500 with most of it blank would assert we had
// looked at the whole band and found it empty — the same lie as rendering a
// spectrum of zeroes.
//
// THE BINS ARE PEAKS, NOT AVERAGES. The sensor aggregates ~666 sweeps/sec down
// to one record per channel per window and keeps the per-bin MAXIMUM, because a
// brief microwave burst is what this tier exists to catch and averaging it
// against quiet sweeps is how it hides.
//
// WHERE THE DATA COMES FROM, and what does NOT come with it. The app's Rust half
// subscribes to the sensor's sealed UDP stream, verifies the Ed25519 signature,
// decrypts and decodes; this view receives already-authenticated records over a
// Tauri event and holds NO key of any kind.
import { useEffect, useMemo, useState } from "react";
import { listen } from "@tauri-apps/api/event";
import { Box } from "@/shared/ui/layout/Box";
import { Stack } from "@/shared/ui/layout/Stack";
import { Text } from "@/shared/ui/typography/Text";

export type SpectrumBins = {
  freqMhz: number;
  sweeps: number;
  noiseDbm: number;
  peakMagnitude: number;
  peakBin: number;
  binMax: number[];
  /** Milliseconds since the subscription started. Absent on a fixture. */
  receivedAtMs?: number;
};

/** What the subscription can say about whether the sensor is still there. */
export type LivenessState = "never-heard" | "healthy" | "late" | "silent";

export type Liveness = { state: LivenessState; sinceMs: number; overdueByMs: number };

/** Before anything at all has arrived — NOT a healthy stream. */
export const NEVER_HEARD: Liveness = { state: "never-heard", sinceMs: 0, overdueByMs: 0 };

/** One observed window: a record, and when it landed. */
export type Row = { at: number; bins: SpectrumBins };

/** The frequency extent of the waterfall, in MHz. */
export type Span = { loMhz: number; hiMhz: number };

/** How many windows the waterfall keeps. At ~1 Hz this is about two minutes. */
export const HISTORY = 120;

/** An HT20 channel is 20 MHz wide, however many bins the radio reports. */
export const CHANNEL_WIDTH_MHZ = 20;

/**
 * How far above the noise floor the colour ramp saturates, in dB.
 *
 * A byte of magnitude is 20·log10(255) ≈ 48 dB of range, so 48 spends the whole
 * ramp on signal that is actually representable rather than compressing it into
 * the bottom third.
 */
export const RAMP_DB = 48;

/** Centre frequency of one FFT bin. */
export function binFrequencyMhz(centreMhz: number, bin: number, bins: number): number {
  return centreMhz - CHANNEL_WIDTH_MHZ / 2 + (CHANNEL_WIDTH_MHZ * (bin + 0.5)) / bins;
}

/** The [low, high] MHz edges of one bin — what the waterfall needs to place it. */
export function binEdgesMhz(centreMhz: number, bin: number, bins: number): [number, number] {
  const lo = centreMhz - CHANNEL_WIDTH_MHZ / 2 + (CHANNEL_WIDTH_MHZ * bin) / bins;
  return [lo, lo + CHANNEL_WIDTH_MHZ / bins];
}

/**
 * Estimated signal strength for one bin, in dBm.
 *
 * ESTIMATED, AND SAID TO BE, WHEREVER IT IS SHOWN. ath9k reports a per-bin FFT
 * magnitude and a per-window noise floor, not a calibrated power. This is
 * decibels above that reported floor — `noise + 20·log10(magnitude)` — which is
 * the honest reading of what the radio hands over. A number that looks
 * calibrated and is not will be read as calibrated.
 *
 * A zero magnitude is the floor itself rather than negative infinity.
 */
export function binDbm(magnitude: number, noiseDbm: number): number {
  if (magnitude <= 0) return noiseDbm;
  return noiseDbm + 20 * Math.log10(magnitude);
}

type Stop = { at: number; rgb: [number, number, number] };

/** The ramp, dark to hot. Classic for a waterfall, and legible on a dark ground. */
const RAMP: Stop[] = [
  { at: 0.0, rgb: [10, 12, 24] },
  { at: 0.25, rgb: [24, 60, 150] },
  { at: 0.5, rgb: [20, 160, 160] },
  { at: 0.7, rgb: [90, 200, 70] },
  { at: 0.85, rgb: [240, 200, 50] },
  { at: 1.0, rgb: [240, 70, 50] },
];

/** Colour for a strength, as a fraction of the ramp. Pure, so the scale is testable. */
export function rampColor(t: number): string {
  const x = Math.max(0, Math.min(1, t));
  let lo = RAMP[0];
  let hi = RAMP[RAMP.length - 1];
  for (let i = 0; i < RAMP.length - 1; i++) {
    if (x >= RAMP[i].at && x <= RAMP[i + 1].at) {
      lo = RAMP[i];
      hi = RAMP[i + 1];
      break;
    }
  }
  const span = hi.at - lo.at || 1;
  const k = (x - lo.at) / span;
  const c = (a: number, b: number) => Math.round(a + (b - a) * k);
  return `rgb(${c(lo.rgb[0], hi.rgb[0])},${c(lo.rgb[1], hi.rgb[1])},${c(lo.rgb[2], hi.rgb[2])})`;
}

/** Where a strength sits on the ramp, given the floor it is measured against. */
export function strengthFraction(dbm: number, noiseDbm: number): number {
  return Math.max(0, Math.min(1, (dbm - noiseDbm) / RAMP_DB));
}

/** Colour for one bin's magnitude. */
export function strengthColor(magnitude: number, noiseDbm: number): string {
  return rampColor(strengthFraction(binDbm(magnitude, noiseDbm), noiseDbm));
}

/**
 * The frequency extent of everything observed — never a band constant.
 *
 * `null` when nothing has arrived, so the caller renders the empty state rather
 * than an axis with no meaning.
 */
export function spanOf(rows: Row[]): Span | null {
  let lo = Infinity;
  let hi = -Infinity;
  for (const r of rows) {
    const n = r.bins.binMax.length;
    if (n === 0) continue;
    lo = Math.min(lo, binEdgesMhz(r.bins.freqMhz, 0, n)[0]);
    hi = Math.max(hi, binEdgesMhz(r.bins.freqMhz, n - 1, n)[1]);
  }
  return Number.isFinite(lo) && Number.isFinite(hi) && hi > lo ? { loMhz: lo, hiMhz: hi } : null;
}

/** Push a record onto the history, newest first, bounded. */
export function pushRow(rows: Row[], bins: SpectrumBins, at: number, cap = HISTORY): Row[] {
  return [{ at, bins }, ...rows].slice(0, cap);
}

/** The colour a frequency region gets when NOTHING was looked at there. */
export const UNOBSERVED = "rgba(255,255,255,0.045)";

const pct = (v: number) => `${Math.round(v * 1000) / 1000}%`;

/**
 * One row as a CSS gradient with hard stops — one element per window instead of
 * one per bin, which is the difference between 120 nodes and 6,720.
 *
 * A ROW COVERS ONLY WHAT IT OBSERVED. The rest of the span is [`UNOBSERVED`],
 * visibly not the same as quiet: a hopping radio's rows are honest stripes of
 * where it actually was, and painting the gaps dark would claim it heard silence
 * on channels it never visited.
 */
export function rowGradient(row: Row, span: Span): string {
  const width = span.hiMhz - span.loMhz;
  const n = row.bins.binMax.length;
  if (width <= 0 || n === 0) return UNOBSERVED;
  const at = (mhz: number) => ((mhz - span.loMhz) / width) * 100;
  const parts: string[] = [];
  const [firstLo] = binEdgesMhz(row.bins.freqMhz, 0, n);
  const [, lastHi] = binEdgesMhz(row.bins.freqMhz, n - 1, n);
  const head = at(firstLo);
  const tail = at(lastHi);
  if (head > 0) parts.push(`${UNOBSERVED} 0%`, `${UNOBSERVED} ${pct(head)}`);
  for (let i = 0; i < n; i++) {
    const [lo, hi] = binEdgesMhz(row.bins.freqMhz, i, n);
    const c = strengthColor(row.bins.binMax[i], row.bins.noiseDbm);
    parts.push(`${c} ${pct(at(lo))}`, `${c} ${pct(at(hi))}`);
  }
  if (tail < 100) parts.push(`${UNOBSERVED} ${pct(tail)}`, `${UNOBSERVED} 100%`);
  return `linear-gradient(to right, ${parts.join(", ")})`;
}

/** Human-readable age, for a label rather than a calculation. */
export function ageLabel(ms: number): string {
  if (ms < 1000) return `${ms}ms`;
  const s = Math.floor(ms / 1000);
  if (s < 120) return `${s}s`;
  return `${Math.floor(s / 60)}m`;
}

/**
 * Whether what is on screen may be presented as the air RIGHT NOW.
 *
 * Only `healthy` may. `late` and `silent` still render the history — it is the
 * most recent truth there is — but marked, because the alternative is a display
 * that quietly ages into a lie.
 */
export function isCurrent(l: Liveness): boolean {
  return l.state === "healthy";
}

/**
 * What an empty panel should say, given whether the sensor is being heard.
 *
 * THE TWO CASES LOOK IDENTICAL AND ARE NOT THE SAME PROBLEM. A subscriber that
 * hears nothing has a network, key or sensor fault. One that hears the sensor
 * perfectly and receives no SPECTRUM has a radio fault. Measured once, at
 * length: an hour of establishing from outside what this line says in six words.
 */
export function emptyStateDiagnosis(l: Liveness): string {
  switch (l.state) {
    case "never-heard":
      return "Nothing has been heard from the sensor at all — check the address and the keys.";
    case "healthy":
      return `The sensor IS heard (${ageLabel(l.sinceMs)} ago) but is sending no spectrum — its radio is producing nothing.`;
    case "late":
      return `The sensor is late by ${ageLabel(l.overdueByMs)} and has sent no spectrum.`;
    case "silent":
      return `The sensor has been silent for ${ageLabel(l.sinceMs)} — treat the stream as gone.`;
  }
}

/**
 * Subscribe to the app's LAN stream. Returns the observed history and what the
 * subscription can say about the sensor's liveness.
 *
 * The liveness event carries the CURRENT verdict rather than only transitions,
 * so a window opened long after the last change still learns the state — "no
 * liveness yet" must not render the same as "healthy".
 */
export function useLanSpectrum(): { rows: Row[]; liveness: Liveness } {
  const [rows, setRows] = useState<Row[]>([]);
  const [liveness, setLiveness] = useState<Liveness>(NEVER_HEARD);

  useEffect(() => {
    let disposed = false;
    const spectrum = listen<SpectrumBins>("lan://spectrum", (e) => {
      if (!disposed) setRows((prev) => pushRow(prev, e.payload, e.payload.receivedAtMs ?? Date.now()));
    });
    const live = listen<Liveness>("lan://liveness", (e) => {
      if (!disposed) setLiveness(e.payload);
    });
    return () => {
      disposed = true;
      void spectrum.then((un) => un());
      void live.then((un) => un());
    };
  }, []);

  return { rows, liveness };
}

function Scale({ noiseDbm }: { noiseDbm: number }) {
  const steps = [0, 0.25, 0.5, 0.7, 0.85, 1];
  return (
    <Box style={{ display: "flex", alignItems: "center", gap: 8, width: "100%" }}>
      <Text as="span" mono tone="dim" style={{ fontSize: 11 }}>
        {noiseDbm} dBm
      </Text>
      <Box
        style={{
          flex: 1,
          height: 8,
          borderRadius: 2,
          background: `linear-gradient(to right, ${steps.map((s) => `${rampColor(s)} ${s * 100}%`).join(", ")})`,
        }}
      />
      <Text as="span" mono tone="dim" style={{ fontSize: 11 }}>
        {noiseDbm + RAMP_DB} dBm (est.)
      </Text>
    </Box>
  );
}

function Axis({ span }: { span: Span }) {
  const ticks = useMemo(() => {
    const out: number[] = [];
    const first = Math.ceil(span.loMhz / 5) * 5;
    for (let f = first; f <= span.hiMhz; f += 5) out.push(f);
    return out;
  }, [span.loMhz, span.hiMhz]);
  const width = span.hiMhz - span.loMhz || 1;
  return (
    <Box style={{ position: "relative", height: 16, width: "100%" }}>
      {ticks.map((f) => (
        <Text
          key={f}
          as="span"
          mono
          tone="dim"
          style={{
            position: "absolute",
            left: `${((f - span.loMhz) / width) * 100}%`,
            transform: "translateX(-50%)",
            fontSize: 11,
            whiteSpace: "nowrap",
          }}
        >
          {f}
        </Text>
      ))}
    </Box>
  );
}

function Waterfall({ rows, liveness }: { rows: Row[]; liveness: Liveness }) {
  const span = useMemo(() => spanOf(rows), [rows]);

  if (!span) {
    // Never render an empty display as a quiet band: no data and clear air look
    // identical here, and only one of them is good news.
    return (
      <Box style={{ padding: 24, width: "100%" }}>
        <Text as="div" mono tone="dim">
          No spectrum received yet — this is NOT a quiet band.
        </Text>
        <Text as="div" mono style={{ marginTop: 10 }}>
          {emptyStateDiagnosis(liveness)}
        </Text>
        <Text as="div" mono tone="dim" style={{ marginTop: 6, fontSize: 12 }}>
          The sensor emits one aggregated record per channel per window. If nothing
          arrives, check the group and the keys before concluding the air is clear.
        </Text>
      </Box>
    );
  }

  const newest = rows[0].bins;
  const current = isCurrent(liveness);
  return (
    <Stack gap={6} style={{ padding: 12, width: "100%", height: "100%", minHeight: 0 }}>
      <Text as="div" mono style={{ fontSize: 12 }}>
        {span.loMhz.toFixed(0)}–{span.hiMhz.toFixed(0)} MHz observed · {rows.length} window(s) ·{" "}
        {newest.sweeps} sweeps · noise {newest.noiseDbm} dBm
      </Text>
      {!current && (
        <Text as="div" mono tone="dim" style={{ fontSize: 12 }}>
          {liveness.state === "silent"
            ? `SENSOR SILENT for ${ageLabel(liveness.sinceMs)} — this is the LAST of what it sent, not the air now.`
            : `SENSOR LATE by ${ageLabel(liveness.overdueByMs)} — this is the LAST of what it sent, not the air now.`}
        </Text>
      )}
      <Axis span={span} />
      <Box
        style={{
          width: "100%",
          flex: 1,
          minHeight: 120,
          overflow: "hidden",
          border: "1px solid var(--border)",
          opacity: current ? 1 : 0.55,
          display: "flex",
          flexDirection: "column",
        }}
      >
        {rows.map((r) => (
          <Box
            key={`${r.at}-${r.bins.freqMhz}`}
            title={`${r.bins.freqMhz} MHz · ${r.bins.sweeps} sweeps · peak ${r.bins.peakMagnitude} at bin ${r.bins.peakBin}`}
            style={{ width: "100%", flex: "0 0 4px", background: rowGradient(r, span) }}
          />
        ))}
      </Box>
      <Scale noiseDbm={newest.noiseDbm} />
      <Text as="div" mono tone="dim" style={{ fontSize: 11 }}>
        newest on top · colour is signal strength ESTIMATED as dB above the reported noise floor ·
        per-bin PEAK across each window (not a mean) · a faint band is frequency nobody looked at
      </Text>
    </Stack>
  );
}

function Assistant({ notes }: { notes: string[] }) {
  return (
    <Stack gap={6} style={{ padding: 16, overflow: "auto", height: "100%", width: "100%" }}>
      <Text as="div" mono tone="dim" style={{ fontSize: 11 }}>
        ASSISTANT
      </Text>
      {notes.length === 0 ? (
        <Text as="div" mono tone="dim">
          Nothing to report yet.
        </Text>
      ) : (
        notes.map((n, i) => (
          <Text as="div" mono key={i} style={{ fontSize: 12 }}>
            {n}
          </Text>
        ))
      )}
    </Stack>
  );
}

/**
 * The analyzer window: waterfall above, assistant below.
 *
 * Presentational on purpose — it takes what to draw rather than fetching it, so
 * every state it can be in is reachable from a test without a socket.
 * [`LiveSpectrumAnalyzer`] is the half that subscribes.
 *
 * Width and height are STATED at every level, not inherited: percentage heights
 * resolve against a definite parent and `min-height` does not make one, and a
 * stretched flex child collapses to content width the moment an ancestor stops
 * being definite. Both were seen on screen with a green gate, because jsdom has
 * no layout at all.
 */
export function SpectrumAnalyzer({
  rows = [],
  liveness = NEVER_HEARD,
  notes = [],
}: {
  rows?: Row[];
  liveness?: Liveness;
  notes?: string[];
}) {
  return (
    <Stack style={{ height: "100%", width: "100%" }}>
      <Box
        style={{
          flex: "1 1 62%",
          minHeight: 0,
          width: "100%",
          borderBottom: "1px solid var(--border)",
        }}
      >
        <Waterfall rows={rows} liveness={liveness} />
      </Box>
      <Box style={{ flex: "1 1 38%", minHeight: 0, width: "100%" }}>
        <Assistant notes={notes} />
      </Box>
    </Stack>
  );
}

/** The analyzer, wired to the live stream. What the detached window renders. */
export function LiveSpectrumAnalyzer() {
  const { rows, liveness } = useLanSpectrum();
  return <SpectrumAnalyzer rows={rows} liveness={liveness} />;
}
